<style scoped lang="scss" src="./fundraiser-hub-block.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../../components/icon/icon";
import Meter from "../../components/meter/meter";
import Button from "../../components/button/button";
import { IconShape } from "../../components/icon/icon.constants.js";
import { MeterMode } from "../../components/meter/meter.constants.js";
import { ButtonMode, ButtonSize } from "../../components/button/button.constants.js";
import { HubBlockMode, HubBlockModeValues } from "./fundraiser-hub-block.constants.js";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import Row from "../row/row";
import Column from "../column/column";
import DesktopOnly from "../desktop-only/desktop-only";
import MobileOnly from "../mobile-only/mobile-only";
import { has } from "../../util/has";
import Switch from "../v-switch/v-switch.vue";

@Component({
  components: {
    DesktopOnly,
    MobileOnly,
    Row,
    Column,
    Icon,
    Meter,
    Button,
    "v-switch": Switch,
  }
})
export default class FundraiserHubBlock extends Vue {
  @Prop({
    type: String,
    default: HubBlockMode.GOAL,
    validator: has(HubBlockModeValues)
  }) mode;

  @Prop({ type: Number, default: 0 }) goal;
  @Prop({ type: Number, default: 0 }) collected;
  @Prop({ type: Number, default: 0 }) collectedToday;
  @Prop({ type: Number, default: 0}) donorNumber;
  @Prop({ type: Number, default: 0}) avgDonation;
  @Prop({ type: Number, default: 0 }) visitorNumber;
  @Prop({ type: Number, default: 0 }) visitorToday;
  @Prop({ type: String, default: "" }) pageName;
  @Prop({ type: String, default: "" }) pageImage;
  @Prop({ type: String, default: "" }) pageTitle;
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  IconShape = IconShape;
  MeterMode = MeterMode;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  HubBlockMode = HubBlockMode;

  get hubBlockMode() {
    return this.mode;
  }
}
</script>

<template>
  <div class="FundraiserHubBlock">
    <div class="FundraiserHubBlock__Content">
      <v-switch :key="hubBlockMode" :value="hubBlockMode">
        <template v-slot:[HubBlockMode.GOAL]>
          <div class="FundraiserHubBlock__Upper">
            <Icon :shape="IconShape.PIGGY_BANK" :size="48" :color="'#57BFA1'" />
          </div>
          <div class="FundraiserHubBlock__Middle">
            <Meter
              :mode="MeterMode.GOAL"
              :goal="goal"
              :collected="collected"
              :collectedToday="collectedToday"
              :currency="currency"
            />
          </div>
          <div
            :class="[
              'FundraiserHubBlock__Lower',
              'FundraiserHubBlock__OneButton'
            ]"
          >
            <Button
              class="FundraiserHubBlock__Button"
              label="Edit goal"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onEditGoal')"
            />
          </div>
        </template>
        <template v-slot:[HubBlockMode.DONOR]>
          <div class="FundraiserHubBlock__Upper">
            <Icon
              :shape="IconShape.CASH_MESSAGE"
              :size="48"
              :color="'#57BFA1'"
            />
          </div>
          <div
            :class="['FundraiserHubBlock__Middle', 'FundraiserHubBlock__Flex']"
          >
            <div class="FundraiserHubBlock__Donor">
              <DesktopOnly>
                <Row class="FundraiserHubBlock--center">
                  <span>You have</span>
                  <span class="FundraiserHubBlock__DonorNumber">{{
                    `${donorNumber.toLocaleString()} donors.`
                  }}</span>
                </Row>
              </DesktopOnly>
              <MobileOnly>
                <Column class="FundraiserHubBlock--center">
                  <span>You have</span>
                  <span class="FundraiserHubBlock__DonorNumber">{{
                    `${donorNumber.toLocaleString()} donors.`
                  }}</span>
                </Column>
              </MobileOnly>
            </div>
            <div class="FundraiserHubBlock__AvgNumber">
              {{ `Average donation is $${avgDonation.toFixed(2)}.` }}
            </div>
          </div>
          <div
            :class="[
              'FundraiserHubBlock__Lower',
              'FundraiserHubBlock__TwoButtons'
            ]"
          >
            <Button
              class="FundraiserHubBlock__Button"
              label="Invite more donors"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onInviteMoreDonors')"
            />
            <Button
              class="FundraiserHubBlock__Button"
              label="Download donor list"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onViewDonorList')"
            />
          </div>
        </template>
        <template v-slot:[HubBlockMode.VISITOR]>
          <div class="FundraiserHubBlock__Upper">
            <Icon
              :shape="IconShape.FILTER_HEART"
              :size="48"
              :color="'#57BFA1'"
            />
          </div>
          <div
            :class="['FundraiserHubBlock__Middle', 'FundraiserHubBlock__Flex']"
          >
            <div class="FundraiserHubBlock__Visitor">
              <DesktopOnly>
                <Row class="FundraiserHubBlock--center">
                  <span>You've had</span>
                  <span class="FundraiserHubBlock__VisitorNumber">{{
                    `${visitorNumber.toLocaleString()} visits.`
                  }}</span>
                </Row>
              </DesktopOnly>
              <MobileOnly>
                <Column class="FundraiserHubBlock--center">
                  <span>You've had</span>
                  <span class="FundraiserHubBlock__VisitorNumber">{{
                    `${visitorNumber.toLocaleString()} visits.`
                  }}</span>
                </Column>
              </MobileOnly>
            </div>
            <div class="FundraiserHubBlock__Today">
              {{ `${visitorToday.toLocaleString()} visitors today.` }}
            </div>
          </div>
          <div
            :class="[
              'FundraiserHubBlock__Lower',
              'FundraiserHubBlock__TwoButtons'
            ]"
          >
            <div class="FundraiserHubBlock__NameEditor">
              <div class="FundraiserHubBlock__EditorContent">
                <div class="FundraiserHubBlock__EditLeft">
                  <div class="FundraiserHubBlock__Title">Your Page</div>
                  <div class="FundraiserHubBlock__Name" :title="pageName">
                    {{ `/${pageName}` }}
                  </div>
                </div>
                <div class="FundraiserHubBlock__EditSign">
                  <Icon :shape="IconShape.EDIT" :size="24" :color="'#DADCE8'" />
                </div>
              </div>
            </div>
            <Button
              class="FundraiserHubBlock__Button"
              label="Edit your page"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onEditYourPage')"
            />
          </div>
        </template>
        <template v-slot:[HubBlockMode.PAGE]>
          <div class="FundraiserHubBlock__Upper">
            <div class="FundraiserHubBlock__PageTitle">
              <span>{{ pageTitle }}</span>
            </div>
          </div>
          <div class="FundraiserHubBlock__Middle">
            <div class="FundraiserHubBlock__PageImage">
              <img :src="pageImage" />
            </div>
          </div>
          <div
            :class="[
              'FundraiserHubBlock__Lower',
              'FundraiserHubBlock__TwoButtons'
            ]"
          >
            <Button
              class="FundraiserHubBlock__Button"
              label="Edit page"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onEditPage')"
            />
            <Button
              class="FundraiserHubBlock__Button"
              label="View page"
              :mode="ButtonMode.SUBTLE"
              :size="ButtonSize.LARGE"
              @click="$emit('onViewPage')"
            />
          </div>
        </template>
      </v-switch>
    </div>
  </div>
</template>
